mapper.select:
SELECT
    COUNT(*) AS total,
    COUNT(*) FILTER (WHERE status = 'DRAFT') AS draft,
    COUNT(*) FILTER (WHERE status = 'PUBLISHED') AS published,
    COUNT(*) FILTER (WHERE status = 'CANCELLED') AS cancelled,
    COUNT(*) FILTER (WHERE status = 'COMPLETED') AS completed,
    COUNT(*) FILTER (
        WHERE status = 'PUBLISHED'
          AND sales_start_time <= #{now}
          AND sales_end_time >= #{now}
    ) AS on_sale_now,
    COUNT(*) FILTER (
        WHERE status = 'PUBLISHED'
          AND start_time >= #{now}
          AND start_time < #{startingSoonBefore}
    ) AS starting_soon
FROM events

SELECT COUNT(*)
FROM orders
WHERE status = #{status}

SELECT COUNT(*)
FROM tickets
WHERE status = #{status}
